import {GameService, ProbabilityPolicy, RuleError, basisPoints, clone, token} from './domain.js';
import {LocalRepository} from './storage.js';
import {THEMES, getTheme, getAppearance, themedPrizes} from './themes.js';
import {getContent, contentRevision, contentVariables, formatContent, contentTheme} from './content.js';
import {ContentEditor, brandMarkup} from './content-editor.js';
import {icon, escapeHTML as e, dateLabel, dateTimeLabel, percentLabel, WheelRenderer, SoundController, confetti} from './visuals.js';

const statusOf = v => v.redeemedAt ? 'used' : +new Date(v.expiresAt) <= Date.now() ? 'expired' : 'active';
const redemptionSource = v => v.redeemedByType === 'customer' ? 'Khách hàng tự xác nhận' : 'Nhân viên xác nhận';
const statusText = status => ({active:'Còn hiệu lực',used:'Đã sử dụng',expired:'Đã hết hạn'}[status]);
const symbol = p => `<span class="reward-symbol">${p.image ? `<img src="${e(p.image)}" alt="" loading="lazy">` : icon(p.icon)}</span>`;
const field = (name,label,value='',type='text',extra='') => `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${e(value)}" ${extra}></div>`;
const datetimeLocal = iso => iso ? new Date(+new Date(iso)-new Date(iso).getTimezoneOffset()*60000).toISOString().slice(0,16) : '';
const asISO = value => value ? new Date(value).toISOString() : '';

class App {
  constructor() {
    this.repository = new LocalRepository(); this.game = new GameService(this.repository); this.sound = new SoundController();
    this.userId = localStorage.getItem('anni-demo-session'); this.source = 'free'; this.walletFilter = 'active'; this.reportFilter = ''; this.reportStatus = 'all'; this.spinning = false; this.draft = null; this.editingId = null;
    document.addEventListener('click', event => this.onClick(event));
    document.addEventListener('submit', event => {if(event.target.matches('[data-form]')) {event.preventDefault();this.onForm(event.target);}});
    document.addEventListener('input', event => this.onInput(event));
    window.addEventListener('hashchange', () => {if(!this.spinning){this.draft=null;this.themeDraft=null;this.closeDialog();this.render();window.scrollTo({top:0});}});
    window.addEventListener('storage', event => {if(event.key===this.repository.key)this.refreshVoucherViews();});
    this.layoutObserver = new ResizeObserver(() => this.measureMobileLayout());
    this.defaultFavicon=document.querySelector('link[rel="icon"]').getAttribute('href');
    window.addEventListener('beforeunload',event=>{if(this.contentEditor?.dirty){event.preventDefault();event.returnValue='';}});
    this.render();
  }
  get user() { return this.state.users.find(u=>u.id===this.userId); }
  get route() { const path=location.hash.replace(/^#\/?/,'');return ['play','wallet','rules','admin','admin/prizes','admin/codes','admin/reports','admin/redeem','admin/settings','admin/themes','admin/content'].includes(path)?path:'play'; }
  get appearance(){return getAppearance(this.state.settings);}
  get content(){return this.presentation||getContent(this.state.settings);}
  get theme(){return contentTheme(this.appearance.theme,this.content);}
  contentText(key,extra={}){return formatContent(this.content.text[key],contentVariables(this.content,{customer:this.user?.name||this.user?.phone||'bạn',dailyFree:this.state.settings.dailyFree,...extra}));}
  text(key,extra={}){return e(this.contentText(key,extra));}
  toast(message) {const t=document.getElementById('toast');t.textContent=message;t.className='visible';clearTimeout(this.toastTimer);this.toastTimer=setTimeout(()=>t.className='',4200);}
  render() {
    this.state=this.game.snapshot();if(this.userId&&!this.user){this.userId=null;localStorage.removeItem('anni-demo-session');}
    this.presentation=getContent(this.state.settings);
    const route=this.route,admin=route.startsWith('admin');
    document.documentElement.dataset.theme=admin?'anni':this.theme.id;
    document.documentElement.dataset.festival=String(!admin&&route==='play'&&this.theme.id!=='anni');
    document.querySelector('meta[name="theme-color"]').content=!admin&&route==='play'&&this.theme.scene?'#211b21':'#F7F3EA';
    const balance=this.playBalance();
    if(balance[this.source]===0){if(balance.free>0)this.source='free';else if(balance.earned>0)this.source='earned';}
    const app=document.getElementById('app');app.dataset.view=admin?'admin':'customer';app.dataset.route=route;app.dataset.festival=String(!admin&&route==='play'&&this.theme.id!=='anni');
    document.title=`${admin?'Quản trị':route==='wallet'?this.contentText('walletTitle'):this.contentText('gameTitle')} · ${this.content.brand.name}`;
    document.querySelector('link[rel="icon"]').href=this.content.brand.logo||this.defaultFavicon;
    document.getElementById('app').innerHTML=`<div class="demo-bar"><span class="dot"></span>BẢN TRẢI NGHIỆM · Quà mẫu không có giá trị sử dụng</div><div class="shell">${this.header(admin)}<main id="main">${admin?this.admin():route==='wallet'?this.wallet():route==='rules'?this.rules():this.play()}</main>${admin?'':this.footer()}</div>${this.mobileNav()}`;
    if(route==='admin/redeem'&&this.staffLookupCode){document.querySelector('.redeem-form [name=code]').value=this.staffLookupCode;this.lookup(this.staffLookupCode);}
    if(route==='play'){this.wheel=new WheelRenderer(document.querySelector('#wheel'));this.wheel.draw(themedPrizes(this.state.prizes,this.theme.id));this.wheel.rotation=this.wheelAngle||0;this.wheel.canvas.style.transform=`rotate(${this.wheel.rotation}deg)`;}
    if(route==='admin/themes')new WheelRenderer(document.getElementById('theme-preview-wheel')).draw(themedPrizes(this.state.prizes,this.themeDraft.theme));
    if(route==='admin/content')this.contentEditor.draw(this.state.prizes);
    this.layoutObserver.disconnect();
    for(const element of document.querySelectorAll('.demo-bar,.site-header,.mobile-dock,.mobile-play-title'))this.layoutObserver.observe(element);
    this.measureMobileLayout();
  }
  measureMobileLayout(){
    const height=selector=>document.querySelector(selector)?.getBoundingClientRect().height||0;
    const app=document.getElementById('app');
    app.style.setProperty('--mobile-title-space',`${height('.mobile-play-title')}px`);
    app.style.setProperty('--mobile-top-space',`${height('.demo-bar')+height('.site-header')}px`);
    app.style.setProperty('--mobile-bottom-space',`${height('.mobile-dock')}px`);
    document.documentElement.style.setProperty('--mobile-toast-space',`${height('.mobile-dock')+12}px`);
  }
  playBalance(){return this.user?this.game.balance(this.userId,this.state):{free:this.state.settings.dailyFree,earned:0};}
  sourceSwitch(balance){return `<div class="source-switch" role="group" aria-label="Nguồn lượt quay">${[['free','Miễn phí'],['earned','Từ hóa đơn']].map(([value,label])=>`<button data-action="source" data-value="${value}" class="${this.source===value?'selected':''}" aria-pressed="${this.source===value}">${label} · ${balance[value]}</button>`).join('')}</div>`;}
  header(admin) {
    return `<header class="site-header"><a href="#play" class="brand" aria-label="${e(this.content.brand.name)} — Trang chơi">${brandMarkup(this.content)}</a><nav class="nav" aria-label="Điều hướng chính"><a href="#play" class="${this.route==='play'?'active':''}">${this.text('gameTitle')}</a><a href="#wallet" class="${this.route==='wallet'?'active':''}">${this.text('walletTitle')}</a><a href="#rules" class="${this.route==='rules'?'active':''}">${this.text('rulesNav')}</a></nav><span class="mobile-header-label">${this.route==='wallet'?this.text('walletTitle'):this.route==='rules'?this.text('rulesNav'):this.theme.id==='anni'?this.text('gameTitle'):e(this.theme.occasion)}</span><div class="header-right">${admin?'<a class="admin-link" href="#play">← Trở về vòng quay</a>':'<a class="admin-link" href="#admin">Quản trị demo ↗</a>'}<button class="profile" data-action="account" aria-label="Tài khoản">${icon('user')}<span>${this.user?e(this.user.name||this.user.phone):'Khách trải nghiệm'}</span></button></div></header>`;
  }
  mobileNav(){
    const balance=this.playBalance(),hasTurns=balance.free+balance.earned>0,active=this.state.settings.active;
    const dualSource=balance.free>0&&balance.earned>0;
    const label=!active?'ĐANG TẠM DỪNG':!hasTurns?'ĐÃ HẾT LƯỢT':this.contentText('spinButton')+' · '+balance[this.source]+' LƯỢT';
    const hint=!active?this.content.brand.name+' sẽ sớm mở lại vòng quay.':!hasTurns?'Nhập mã từ thu ngân để nhận thêm lượt.':this.source==='free'?'Lượt miễn phí · Làm mới lúc 00:00':'Đang dùng lượt từ hóa đơn';
    return `<div class="mobile-dock">${this.route==='play'?`<div class="mobile-play-actions">${dualSource?this.sourceSwitch(balance):`<p class="mobile-balance-hint">${e(hint)}</p>`}<div class="mobile-action-row"><button id="mobile-spin-btn" class="btn" data-action="spin" ${!active||!hasTurns?'disabled':''}>${icon('wheel')}<span>${e(label)}</span>${icon('arrow')}</button><button class="btn secondary mobile-code-button" data-action="code" aria-label="Nhập mã từ thu ngân">${icon('ticket')}<span>${this.text('codeButton')}</span></button></div></div>`:''}<nav class="mobile-nav" aria-label="Điều hướng trên điện thoại">${[['play','wheel','Vòng quay'],['wallet','wallet',this.contentText('walletTitle')],['rules','info',this.contentText('rulesNav')]].map(([r,i,t])=>`<a href="#${r}" class="${this.route===r?'active':''}" ${this.route===r?'aria-current="page"':''}>${icon(i)}<span>${e(t)}</span></a>`).join('')}<button data-action="account">${icon('user')}<span>Tài khoản</span></button></nav></div>`;
  }
  footer(){return `<footer class="footer"><span>${e(this.content.brand.name)}${this.content.brand.slogan?' · '+e(this.content.brand.slogan):''}</span><div class="footer-links"><a href="#rules">Thể lệ chương trình</a><button class="text-button" data-action="demo-info">Thông tin bản demo ${icon('info')}</button></div></footer>`;}
  play(){
    const balance=this.playBalance(),theme=this.theme;
    return `<section class="hero ${theme.scene?'festival-hero':''}">${this.themeDecor(theme,this.appearance.decorations)}<h1 class="mobile-play-title serif">${e(theme.mobileLead)} <em>${e(theme.mobileEmphasis)}</em></h1><div class="hero-copy"><div class="eyebrow">${e(theme.eyebrow)}</div><h1 class="serif">${e(theme.headline)}<br>${e(theme.lead)}<em>${e(theme.emphasis)}</em></h1><p class="hero-description">${e(theme.intro)}<br>${e(theme.subline)}</p><div class="hero-small">${icon('cup')}${this.text('heroNote')}</div><div class="play-card"><div class="play-card-top"><div class="balance-label">${icon('gift')}<span>${this.source==='free'?'Lượt miễn phí hôm nay':'Lượt từ hóa đơn'}<small>${this.source==='free'?'Làm mới mỗi ngày lúc 00:00':'Nhận thêm lượt bằng mã từ thu ngân'}</small></span></div><strong>${String(balance[this.source]).padStart(2,'0')}</strong></div>${this.sourceSwitch(balance)}<button id="spin-btn" class="btn full spin-btn" data-action="spin" ${!this.state.settings.active?'disabled':''}>${icon('wheel')}<span>${this.state.settings.active?this.text('spinButton'):'CHIẾN DỊCH TẠM DỪNG'}</span>${icon('arrow')}</button><button class="text-button code-open" data-action="code">${icon('ticket')}${this.text('codeHint')}</button></div></div><div class="wheel-stage"><div class="wheel-wrap">${this.wheelLights(theme)}<span class="wheel-pointer"></span><canvas id="wheel" role="img" aria-label="Vòng quay gồm ${this.state.prizes.map(p=>e(p.short)).join(', ')}"></canvas><div class="wheel-hub">${brandMarkup(this.content,'hub')}</div></div><div class="floating-label">${icon(theme.id==='anni'?'gift':theme.motif)}<span>${e(theme.id==='anni'?'Một vòng quay':theme.name)}<strong>${e(theme.message)}</strong></span></div><span class="floating-star">${icon('spark')}</span><p class="wheel-caption">${icon('lock')}Kết quả ngẫu nhiên theo tỷ lệ của chương trình</p><button class="sound-toggle" data-action="sound" aria-label="${this.sound.enabled?'Tắt':'Bật'} âm thanh" aria-pressed="${this.sound.enabled}">${icon(this.sound.enabled?'sound':'mute')}</button></div></section><section class="rewards-section"><div class="section-line"><div><div class="eyebrow">${this.text('rewardsEyebrow')}</div><h2 class="serif">${this.text('rewardsTitle')}</h2></div><a href="#rules" class="text-button">Xem thể lệ ${icon('arrow')}</a></div><div class="reward-grid">${this.state.prizes.filter(p=>p.kind!=='lose').map(p=>`<div class="reward-preview">${symbol(p)}<div><strong>${e(p.short)}</strong><small>${p.stock>0?'Quà trải nghiệm':'Đã hết quà'}</small></div></div>`).join('')}</div></section>`;
  }
  wallet(){
    const all=this.state.vouchers.filter(v=>v.userId===this.userId).slice().reverse(),list=all.filter(v=>statusOf(v)===this.walletFilter);
    return `<section class="page"><div class="page-heading"><div><div class="eyebrow">${this.text('walletEyebrow')}</div><h1 class="serif">${this.text('walletTitle')}</h1><p>${this.user?this.text('walletGreeting'):this.text('walletLogin')}</p></div>${this.user?'<button class="btn secondary" data-action="account">'+icon('user')+'Tài khoản</button>':''}</div>${!this.user?this.empty('wallet','Niềm vui đang đợi bạn','Đăng nhập để xem voucher, hạn dùng và điều kiện nhận quà.','login','Mở ví quà'):`${this.pendingRecovery()?`<div class="notice">${icon('lock')}<span>Bạn có mã khôi phục mới. Hãy lưu mã để có thể mở lại ví trên thiết bị khác khi bản chính thức được triển khai. <button class="text-button" data-action="recovery">Lưu mã khôi phục</button></span></div>`:''}<div class="tabs" role="group" aria-label="Lọc trạng thái voucher">${[['active','Còn hiệu lực'],['used','Đã sử dụng'],['expired','Hết hạn']].map(([k,t])=>`<button data-action="wallet-filter" data-value="${k}" class="${this.walletFilter===k?'selected':''}">${t} · ${all.filter(v=>statusOf(v)===k).length}</button>`).join('')}</div>${list.length?`<div class="wallet-grid">${list.map(v=>this.voucherCard(v)).join('')}</div>`:this.empty('gift',this.walletFilter==='active'&&all.length?'Chưa có voucher còn hiệu lực':this.text('walletEmptyTitle'),this.walletFilter==='active'?(all.length?'Xem mục Đã sử dụng hoặc Hết hạn để kiểm tra những voucher đã nhận.':this.text('walletEmptyBody')):'Chưa có voucher trong nhóm này.','go-play','Đến vòng quay')}`}</section>`;
  }
  voucherCard(v){
    const status=statusOf(v);
    return `<article class="voucher-card ${status==='used'?'voucher-used':''}"><div class="voucher-top">${symbol(v.prize)}<div><small class="voucher-brand">${this.content.brand.logo?`<img src="${e(this.content.brand.logo)}" alt="">`:""}${e(this.content.brand.name)} · VOUCHER MẪU</small><h3>${e(v.prize.name)}</h3></div></div><div class="voucher-body"><p>${e(v.prize.terms)}</p><div class="voucher-bottom"><div><span class="badge ${status==='active'?'':'gray'}">${statusText(status)}</span><p style="min-height:0;margin-top:5px;font-size:10px">Hạn dùng ${dateLabel(v.expiresAt)}</p></div></div>${v.redeemedAt?`<div class="voucher-usage-note">${icon('check')}<span>${e(redemptionSource(v))}<br>${dateTimeLabel(v.redeemedAt)}</span></div>`:''}<div class="voucher-actions"><button class="btn small secondary" data-action="voucher" data-id="${v.id}">Chi tiết ${icon('arrow')}</button>${status==='active'?`<button class="btn small" data-action="use-voucher" data-id="${v.id}">${icon('check')}Sử dụng voucher</button>`:`<button class="btn small secondary" disabled>${statusText(status)}</button>`}</div></div></article>`;
  }
  empty(i,title,text,action,label){return `<div class="empty-state">${icon(i)}<h3>${title}</h3><p>${text}</p><button class="btn" data-action="${action}">${label} ${icon('arrow')}</button></div>`;}
  rules(){let rates;try{rates=ProbabilityPolicy.weights(this.state.prizes,this.state.settings.mode);}catch{rates=[];}
    return `<section class="page"><div class="page-heading"><div><div class="eyebrow">${this.text('rulesEyebrow')}</div><h1 class="serif">${this.text('rulesTitle')}</h1><p>${this.text('rulesIntro')}</p></div></div><div class="rules-layout"><div class="rules-lead">${icon('cup')}<h2 class="serif">${this.text('rulesLeadTitle')}</h2><p>${this.text('rulesLeadBody')}</p><div class="notice">Bản demo: quà, mã và dữ liệu chỉ dùng thử trong trình duyệt hiện tại.</div></div><div><div class="rule-item"><h3>01 · Nhận lượt quay</h3><p>${this.text('rulesTurns')}</p></div><div class="rule-item"><h3>02 · Kết quả & tỷ lệ</h3><p>${this.text('rulesProbability')}</p><div class="table-wrap"><table><thead><tr><th>Kết quả</th><th>Tỷ lệ hiện tại</th></tr></thead><tbody>${rates.map(p=>`<tr><td>${e(p.name)}</td><td>${percentLabel(p.effective)}</td></tr>`).join('')||'<tr><td colspan="2">Đang tạm dừng để điều chỉnh tỷ lệ.</td></tr>'}</tbody></table></div></div><div class="rule-item"><h3>03 · Lưu & sử dụng voucher</h3><p>${this.text('rulesVoucher')}</p></div><div class="rule-item"><h3>04 · Mã khôi phục & dữ liệu</h3><p>${this.text('rulesRecovery')}</p></div></div></div></section>`;
  }
  admin(){const sections=[['admin','grid','Tổng quan'],['admin/prizes','gift','Phần thưởng'],['admin/codes','ticket','Mã cấp lượt'],['admin/reports','chart','Danh sách trúng'],['admin/redeem','store','Đổi voucher'],['admin/themes','spark','Giao diện & chủ đề'],['admin/content','edit','Nội dung & thương hiệu'],['admin/settings','settings','Thiết lập']];
    return `<div class="admin-shell"><aside class="sidebar"><div class="sidebar-label">QUẢN LÝ CHIẾN DỊCH</div>${sections.map(([r,i,t])=>`<a href="#${r}" class="${this.route===r?'active':''}">${icon(i)}${t}</a>`).join('')}<div class="sidebar-footer">${icon('info')} Khu quản trị mô phỏng.<br>Dữ liệu lưu trên trình duyệt này, chưa có phân quyền máy chủ.</div></aside><div class="admin-main">${this.route==='admin/prizes'?this.prizesAdmin():this.route==='admin/codes'?this.codesAdmin():this.route==='admin/reports'?this.reportsAdmin():this.route==='admin/redeem'?this.redeemAdmin():this.route==='admin/settings'?this.settingsAdmin():this.route==='admin/themes'?this.themesAdmin():this.route==='admin/content'?this.contentAdmin():this.overview()}</div></div>`;
  }
  themeDecor(theme,enabled){
    return enabled&&theme.scene?`<div class="festival-scene" aria-hidden="true"><img src="${e(theme.scene)}" alt="" decoding="async" fetchpriority="high"></div>`:'';
  }
  wheelLights(theme){
    return theme.scene?`<span class="wheel-lights" aria-hidden="true">${Array.from({length:32},(_,i)=>`<i style="left:${50+48*Math.cos(i*Math.PI/16)}%;top:${50+48*Math.sin(i*Math.PI/16)}%"></i>`).join('')}</span>`:'';
  }
  themesAdmin(){
    const current=this.appearance;
    this.themeDraft ||= {...current};
    const draft=this.themeDraft,selected=contentTheme(draft.theme,this.content),changed=draft.theme!==current.theme||draft.decorations!==current.decorations;
    return `${this.adminTitle('Giao diện & chủ đề','Một diện mạo mới cho mỗi mùa vui tại '+e(this.content.brand.name)+'.','<span class="badge">Đang dùng: '+e(getTheme(current.theme).name)+'</span>')}
      <div class="notice">${icon('info')}<span>Bản demo lưu chủ đề trên trình duyệt này. Khi kết nối máy chủ, thiết lập mới có thể áp dụng chung cho mọi khách hàng.</span></div>
      <form data-form="appearance">
        <div class="theme-workspace">
          <section class="theme-library" aria-label="Chọn chủ đề">
            <div class="theme-section-heading"><h2>Chọn không khí cho mùa vui</h2><p>Chọn một chủ đề để xem trước ở bên cạnh.</p></div>
            <div class="theme-options" role="group" aria-label="Bộ chủ đề lễ hội">${THEMES.map(theme=>{
              const colors=theme.palette||this.state.prizes.map(p=>p.color),gradient=colors.map((c,i)=>`${c} ${i*100/colors.length}% ${(i+1)*100/colors.length}%`).join(',');
              return `<button type="button" class="theme-option ${draft.theme===theme.id?'selected':''}" data-theme="${theme.id}" data-action="theme-select" data-value="${theme.id}" aria-pressed="${draft.theme===theme.id}" aria-label="Xem trước ${e(theme.name)}">
                <span class="theme-art" aria-hidden="true">${theme.scene?`<img class="theme-art-image" src="${e(theme.scene)}" alt="" loading="lazy" decoding="async">`:""}<span class="theme-art-label">${e(theme.occasion)}</span><span class="theme-art-motif">${icon(theme.motif)}</span><span class="theme-mini-wheel" style="background:conic-gradient(${gradient})"><span>${e(Array.from(this.content.brand.shortName||this.content.brand.name)[0])}</span></span><span class="theme-selection">${icon('check')}</span></span>
                <span class="theme-option-info"><strong>${e(theme.name)}</strong><span class="theme-option-description">${e(theme.description)}</span><span class="theme-swatches" aria-hidden="true">${theme.swatches.map(c=>`<i style="background:${c}"></i>`).join('')}</span></span>
              </button>`;
            }).join('')}</div>
          </section>
          <aside class="theme-preview-panel" aria-label="Xem trước chủ đề">
            <div class="theme-preview-label"><span>${icon('phone')} Xem trước trên điện thoại</span><span class="badge gold">${changed?'Chưa áp dụng':'Đang sử dụng'}</span></div>
            <div class="theme-preview ${selected.scene?'festival-preview':''}" data-theme="${selected.id}">${this.themeDecor(selected,draft.decorations)}
              <div class="theme-preview-brand"><span class="preview-identity">${brandMarkup(this.content,'mini')}</span><span>${e(selected.occasion)}</span></div>
              <div class="theme-preview-content"><p class="theme-preview-title serif">${e(selected.mobileLead)}<br><em>${e(selected.mobileEmphasis)}</em></p>
                <div class="wheel-wrap">${this.wheelLights(selected)}<span class="wheel-pointer"></span><canvas id="theme-preview-wheel" role="img" aria-label="Xem trước màu vòng quay chủ đề ${e(selected.name)}"></canvas><div class="wheel-hub">${brandMarkup(this.content,'hub')}</div></div>
                <p class="theme-preview-message">${e(selected.message)}</p>
              </div>
              <div class="theme-preview-cta" aria-hidden="true">${icon('wheel')} ${this.text('spinButton')} · 1 LƯỢT ${icon('arrow')}</div>
            </div>
            <label class="check-field theme-decor-toggle"><input type="checkbox" id="theme-decorations" ${draft.decorations?'checked':''}>Hiện hình nền minh họa lễ hội</label>
            <p class="hint">Hình nền, viền vòng quay, lời chào và màn hình nhận quà đổi theo chủ đề. Phần thưởng, tỷ lệ, lượt quay và voucher giữ nguyên. ANNI nguyên bản dùng lại màu ô anh đã thiết lập.</p>
          </aside>
        </div>
        <div class="theme-save-bar"><p>${changed?'Đang xem bản nháp. Bấm áp dụng để lưu.':'Chủ đề đang hiển thị trên giao diện khách hàng.'}</p><div class="form-actions"><button type="button" class="btn secondary" data-action="theme-discard" ${changed?'':'disabled'}>Hủy thay đổi</button><button type="submit" class="btn" ${changed?'':'disabled'}>${icon('check')}Áp dụng chủ đề</button></div></div>
        <p class="inline-error" data-error role="status"></p>
      </form>`;
  }
  contentAdmin(){
    this.contentEditor ||= new ContentEditor(this.state.settings);
    return `${this.adminTitle('Nội dung & thương hiệu','Chỉnh lời chào, logo và cách thương hiệu xuất hiện trong ứng dụng.')}<div class="notice">${icon('info')}<span>Bản demo lưu trên trình duyệt này. Nội dung phần thưởng sửa tại <a href="#admin/prizes">Phần thưởng</a>; tên cửa hàng đổi quà sửa tại <a href="#admin/settings">Thiết lập</a>.</span></div>${this.contentEditor.render(this.state.settings,this.state.prizes)}`;
  }
  contentRestoreDialog(mode){
    const labels={all:'Đưa toàn bộ nội dung về gốc?',section:'Khôi phục nhóm nội dung này?',previous:'Lấy lại bản lưu trước?',discard:'Tải lại nội dung đang dùng?'};
    this.modal(`<div class="modal-symbol">${icon('refresh')}</div><h2 class="serif">${labels[mode]}</h2><p class="intro">${mode==='discard'?'Các chỉnh sửa chưa lưu sẽ được thay bằng nội dung đang dùng.':'Lựa chọn này thay nội dung trong bản nháp. Anh có thể xem lại rồi bấm Lưu nội dung để áp dụng.'}</p><p class="hint">Không thay đổi phần thưởng, tỷ lệ, lượt quay hoặc voucher của khách.</p><div class="form-actions"><button class="btn secondary" data-action="close">Giữ bản nháp</button><button class="btn" data-action="content-restore-confirm" data-value="${mode}">Tiếp tục</button></div>`);
  }
  async contentLogo(file){
    const editor=this.contentEditor,request=++editor.uploadToken;editor.uploading=true;editor.sync(this.state.prizes,this.state.settings);
    const status=document.getElementById('logo-upload-status');if(status)status.textContent='Đang xử lý logo…';
    try{const data=await editor.readLogo(file);if(this.contentEditor!==editor||request!==editor.uploadToken)return;editor.draft.brand.logo=data;this.toast('Đã đưa logo vào bản nháp. Bấm Lưu nội dung để áp dụng.');}
    catch(error){if(this.contentEditor===editor&&request===editor.uploadToken)this.toast(error.message);}
    finally{if(this.contentEditor===editor&&request===editor.uploadToken){editor.uploading=false;if(this.route==='admin/content')this.render();}}
  }
  adminTitle(title,subtitle,button=''){return `<div class="admin-heading"><div><h1 class="serif">${title}</h1><p>${subtitle}</p></div>${button}</div>`;}
  overview(){const s=this.state;return `${this.adminTitle('Một góc nhìn tổng quan','Theo dõi những niềm vui đã trao tại '+e(this.content.brand.name)+'.','<a class="btn secondary" href="#play">'+icon('wheel')+'Xem vòng quay</a>')}<div class="stat-grid">${[['Lượt quay',s.spins.length,'wheel','Tất cả lượt đã hoàn tất'],['Người chơi',s.users.length,'user','Số điện thoại trong bản demo'],['Voucher đã cấp',s.vouchers.length,'gift','Trừ tồn ngay khi trúng'],['Voucher đã dùng',s.redemptions.length,'store','Khách hàng hoặc nhân viên xác nhận']].map(([t,n,i,sub])=>`<div class="stat">${icon(i)}<small>${t}</small><strong>${n.toLocaleString('vi-VN')}</strong><span>${sub}</span></div>`).join('')}</div><div class="notice">${icon('info')}<span>Đây là môi trường thử nghiệm. Chỉnh cấu hình, chơi thử và quay lại để xem số liệu cập nhật. Dữ liệu không đồng bộ giữa các thiết bị.</span></div><div class="overview-grid"><section class="panel"><div class="panel-title"><h2>Phân bổ kết quả</h2><small>${s.spins.length} lượt quay</small></div>${s.prizes.map(p=>{const count=s.spins.filter(x=>x.prize.id===p.id).length;return `<div class="chart-row"><span>${e(p.short)}</span><div class="bar"><i style="width:${s.spins.length?count/s.spins.length*100:0}%;background:${p.color}"></i></div><span>${count}</span></div>`;}).join('')}</section><section class="panel"><div class="panel-title"><h2>Niềm vui gần đây</h2><a href="#admin/reports" class="text-button">Xem tất cả ${icon('arrow')}</a></div>${s.spins.slice(-4).reverse().map(spin=>`<div class="event">${symbol(spin.prize)}<div><strong>${e(spin.prize.short)}</strong><small>${e(spin.phone.slice(0,3)+'••••'+spin.phone.slice(-3))}</small></div><time>${dateTimeLabel(spin.at)}</time></div>`).join('')||'<div class="dashboard-empty">Chưa có lượt quay.<br>Hãy nhập số mẫu ở màn hình chơi để bắt đầu.</div>'}</section></div><section class="panel"><div class="panel-title"><h2>Bắt đầu nhanh</h2><span class="badge">${s.settings.active?'Chiến dịch đang mở':'Đang tạm dừng'}</span></div><div class="admin-quick"><a class="btn light" href="#admin/prizes">${icon('gift')}Chỉnh quà & tỷ lệ</a><a class="btn secondary" href="#admin/codes">${icon('ticket')}Quản lý mã</a><a class="btn secondary" href="#admin/redeem">${icon('store')}Thử đổi voucher</a></div></section>`;}
  prizesAdmin(){this.draft ||= clone(this.state.prizes);let effective=[];try{effective=ProbabilityPolicy.weights(this.draft,this.state.settings.mode);}catch{}
    return `${this.adminTitle('Những món quà từ '+e(this.content.brand.name),'Cấu hình quà, tồn kho và tỷ lệ. Thay đổi chỉ áp dụng cho lượt quay mới.','<button class="btn" data-action="add-prize">'+icon('plus')+'Thêm phần thưởng</button>')}<div class="notice">${icon('info')}<span>Tổng tỷ lệ gốc phải đúng 100%. Quà hết được chia lại cho các ô còn hiệu lực có tỷ lệ gốc &gt; 1%. Đặt 0% để tắt một ô.</span></div><section class="panel"><div class="panel-title"><h2>Danh sách phần thưởng</h2><span class="badge">${this.draft.length} ô trên vòng quay</span></div><div class="table-wrap"><table><thead><tr><th>Phần thưởng</th><th>Tỷ lệ gốc %</th><th>Thực tế</th><th>Quà còn lại</th><th>Hạn dùng</th><th></th></tr></thead><tbody>${this.draft.map((p,i)=>`<tr><td><div class="table-name">${symbol(p)}<div><strong>${e(p.name)}</strong><small>${p.kind==='lose'?'Ô không trúng':p.stock===0?'Đã hết quà':'Voucher mẫu'}</small></div></div></td><td><input class="inline-input" type="number" min="0" max="100" step="0.01" value="${p.weight/100}" data-prize="${i}" data-field="weight" aria-label="Tỷ lệ ${e(p.short)}"></td><td class="numeric" data-effective="${i}">${effective[i]?percentLabel(effective[i].effective):'—'}</td><td>${p.kind==='lose'?'Không giới hạn':`<input class="inline-input" type="number" min="0" step="1" value="${p.stock}" data-prize="${i}" data-field="stock" aria-label="Số lượng ${e(p.short)}">`}</td><td>${p.kind==='lose'?'—':p.days+' ngày'}</td><td><button class="mini-button" data-action="edit-prize" data-id="${p.id}" aria-label="Sửa ${e(p.short)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div><div class="total-row"><span>Tổng tỷ lệ <strong id="total-weight" class="total-number">${percentLabel(this.draft.reduce((n,p)=>n+p.weight,0))}</strong></span><span class="draft-note">Lưu để áp dụng thay đổi</span></div><div class="form-actions"><button class="btn secondary" data-action="discard-prizes">Hủy thay đổi</button><button class="btn" data-action="save-prizes">${icon('check')}Lưu phần thưởng</button></div></section>`;
  }
  codesAdmin(){return `${this.adminTitle('Mã cấp lượt quay','Quản trị tạo nhiều mã, mỗi mã có giới hạn và thời gian riêng.','<button class="btn" data-action="add-code">'+icon('plus')+'Tạo mã mới</button>')}<div class="notice">${icon('ticket')}<span>Thử mã <strong>ANNI2026</strong>: nhận 2 lượt, mỗi số điện thoại dùng 1 lần. Mã cấp lượt khác với mã voucher trúng thưởng.</span></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Mã chương trình</th><th>Lượt / lần</th><th>Đã kích hoạt</th><th>Giới hạn / SĐT</th><th>Hết hạn</th><th>Trạng thái</th><th></th></tr></thead><tbody>${this.state.codes.map(c=>`<tr><td><strong>${e(c.code)}</strong><small style="display:block;color:var(--muted);margin-top:5px">${e(c.branch)}</small></td><td>${c.turns}</td><td>${c.uses.length} / ${c.maxUses}</td><td>${c.perPhone} / ${c.period==='day'?'ngày':'toàn kỳ'}</td><td>${dateLabel(c.ends)}</td><td><span class="badge ${!c.active?'gray':''}">${!c.active?'Tạm khóa':+new Date(c.starts)>Date.now()?'Chưa bắt đầu':+new Date(c.ends)<=Date.now()?'Hết hạn':c.uses.length>=c.maxUses?'Hết lượt':'Đang mở'}</span></td><td><button class="mini-button" data-action="edit-code" data-id="${c.id}" aria-label="Sửa mã ${e(c.code)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div></section>`;}
  reportsAdmin(){return `${this.adminTitle('Danh sách trúng thưởng','Theo dõi người nhận, thời hạn và lịch sử sử dụng voucher.','<button class="btn secondary" data-action="export-report">'+icon('download')+'Xuất CSV</button>')}<div class="filter-row"><input id="report-search" placeholder="Tìm tên, số điện thoại hoặc mã voucher" value="${e(this.reportFilter)}" aria-label="Tìm người trúng thưởng"><select id="report-status" aria-label="Lọc trạng thái">${[['all','Tất cả trạng thái'],['active','Còn hiệu lực'],['used','Đã sử dụng'],['expired','Hết hạn']].map(([v,t])=>`<option value="${v}" ${v===this.reportStatus?'selected':''}>${t}</option>`).join('')}</select></div><section class="panel"><div id="report-table">${this.reportTable()}</div></section>`;}
  reportRows(){const query=this.reportFilter.toLowerCase();return this.state.vouchers.slice().reverse().filter(v=>{const u=this.state.users.find(x=>x.id===v.userId);return (!query||[u?.name,u?.phone,v.code,v.prize.name].join(' ').toLowerCase().includes(query))&&(this.reportStatus==='all'||statusOf(v)===this.reportStatus);});}
  reportTable(){
    const rows=this.reportRows();
    return rows.length?`<div class="table-wrap"><table><thead><tr><th>Khách hàng</th><th>Phần thưởng</th><th>Mã voucher</th><th>Ngày trúng</th><th>Trạng thái</th><th>Xác nhận sử dụng</th><th>Thao tác</th></tr></thead><tbody>${rows.map(v=>{const u=this.state.users.find(x=>x.id===v.userId),status=statusOf(v);return `<tr><td><strong>${e(u?.name||'Chưa nhập tên')}</strong><small style="display:block;margin-top:5px;color:var(--muted)">${e(u?.phone)}</small></td><td>${e(v.prize.name)}</td><td><button class="text-button" data-action="staff-lookup" data-value="${v.code}">${e(v.code)}</button></td><td>${dateTimeLabel(v.at)}</td><td><span class="badge ${status==='active'?'':'gray'}">${statusText(status)}</span></td><td>${v.redeemedAt?`<strong>${e(redemptionSource(v))}</strong><small class="redemption-meta">${e(v.redeemedBy||'Nhân viên')}<br>${dateTimeLabel(v.redeemedAt)}</small>`:'—'}</td><td><button class="btn small ${status==='active'?'':'secondary'}" data-action="confirm-redeem" data-value="${v.code}" ${status!=='active'?'disabled':''}>${status==='active'?'Đánh dấu đã sử dụng':statusText(status)}</button></td></tr>`;}).join('')}</tbody></table></div>`:'<div class="report-empty">Chưa có voucher phù hợp. Kết quả sẽ xuất hiện sau khi chơi thử và trúng quà.</div>';
  }
  redeemAdmin(){return `${this.adminTitle('Đổi voucher tại quầy','Kiểm tra điều kiện và xác nhận sử dụng một lần.')}<section class="panel redeem-box"><div class="modal-symbol">${icon('store')}</div><h2 class="serif" style="font-size:27px;margin-top:18px">Một món quà, một nụ cười.</h2><p class="hint" style="margin-top:10px">Nhập mã voucher khách đưa để kiểm tra trước khi xác nhận.</p><form class="redeem-form" data-form="lookup"><input name="code" placeholder="AC-XXXXXXXXXX" aria-label="Mã voucher" required autocomplete="off"><button class="btn" type="submit">Kiểm tra ${icon('arrow')}</button></form><div class="inline-error" id="redeem-error"></div><div id="redeem-result"></div><div class="notice">${icon('info')}Tài khoản thao tác: Thu ngân demo. Bản chính thức sẽ có đăng nhập và phân quyền nhân viên.</div></section>`;}
  settingsAdmin(){const s=this.state.settings;return `${this.adminTitle('Thiết lập chiến dịch','Chủ động số lượt, thời gian và cách chọn kết quả.')}<form class="panel" data-form="settings"><div class="fields">${field('title','Tên chiến dịch',s.title,'text','required maxlength="80"')}${field('branch','Cửa hàng áp dụng',s.branch,'text','required maxlength="100"')}${field('dailyFree','Lượt miễn phí / SĐT / ngày',s.dailyFree,'number','min="0" max="100" step="1" required')}<div class="field"><label for="f-mode">Cơ chế ngẫu nhiên</label><select name="mode" id="f-mode"><option value="weighted" ${s.mode==='weighted'?'selected':''}>Theo tỷ lệ phần trăm</option><option value="uniform" ${s.mode==='uniform'?'selected':''}>Chia đều các ô đang bật, còn quà</option></select><small>Ô có tỷ lệ gốc 0% luôn bị tắt.</small></div>${field('start','Bắt đầu (giờ trên thiết bị)',datetimeLocal(s.start),'datetime-local')}${field('end','Kết thúc (giờ trên thiết bị)',datetimeLocal(s.end),'datetime-local')}</div><label class="check-field"><input type="checkbox" name="active" ${s.active?'checked':''}>Mở chiến dịch cho khách quay</label><p class="hint">Để trống thời gian để chạy ngay, chưa đặt ngày kết thúc. Lượt miễn phí làm mới lúc 00:00 giờ Việt Nam, không cộng dồn.</p><p class="inline-error" data-error></p><div class="form-actions"><button class="btn" type="submit">${icon('check')}Lưu thiết lập</button></div></form><section class="panel"><div class="panel-title"><h2>Dữ liệu trải nghiệm</h2><span class="badge gold">Chỉ trên thiết bị này</span></div><p class="hint">Khôi phục dữ liệu mẫu sẽ xóa lượt quay, ví quà và cấu hình thử nghiệm trong trình duyệt hiện tại.</p><div class="form-actions"><button class="btn secondary" data-action="export-config">${icon('download')}Xuất cấu hình</button><button class="btn danger" data-action="reset">${icon('refresh')}Khôi phục dữ liệu mẫu</button></div></section>`;}
  modal(content,wide=false){this.closeDialog();const root=document.getElementById('modal-root');root.innerHTML=`<dialog class="dialog ${wide?'wide':''}" aria-label="Thông tin ${e(this.content.brand.name)}"><button class="dialog-close" data-action="close" aria-label="Đóng">${icon('close')}</button><div class="dialog-body">${content}</div></dialog>`;const dialog=root.querySelector('dialog');dialog.showModal();dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)this.closeDialog();}});}
  closeDialog(){this.voucherView=null;const d=document.querySelector('dialog');if(d)d.close();document.getElementById('modal-root').innerHTML='';}
  pendingRecovery(){return this.userId?sessionStorage.getItem('anni-pending-recovery-'+this.userId):null;}
  recoveryMarkup(){const code=this.pendingRecovery();return code?`<div class="recovery-box"><strong>${icon('lock')} MÃ KHÔI PHỤC VÍ QUÀ</strong><code class="secret-code">${e(code)}</code><p>Hãy sao chép và lưu ở nơi riêng tư. Mã này dùng cho toàn bộ ví quà. Trong demo, dữ liệu chỉ tồn tại ở trình duyệt hiện tại.</p><button class="text-button" data-action="copy-recovery">${icon('copy')}Sao chép mã</button></div>`:'';}
  loginDialog(after=''){this.afterLogin=after;this.modal(`<div class="modal-symbol">${icon('phone')}</div><h2 class="serif">${this.text('loginTitle')}</h2><p class="intro">${this.text('loginIntro')}</p><form data-form="login">${field('phone','Số điện thoại','','tel','required inputmode="tel" autocomplete="tel" placeholder="Ví dụ: 0900000001" maxlength="20"')}<button type="button" class="text-button" data-action="sample-phone">Dùng số mẫu 0900000001 ${icon('arrow')}</button><div class="field login-recovery"><label for="f-recovery">Mã khôi phục <span style="color:var(--muted)">(nếu đã có ví quà)</span></label><input name="recovery" id="f-recovery" placeholder="ANNI-…" autocomplete="off"><small>Khách mới để trống. Không nhập dữ liệu khách hàng thật vào demo.</small></div><p class="inline-error" data-error></p><button class="btn full" type="submit">Tiếp tục ${icon('arrow')}</button></form>`);}
  codeDialog(){if(!this.user){this.loginDialog('code');return;}this.modal(`<div class="modal-symbol">${icon('ticket')}</div><h2 class="serif">${this.text('codeTitle')}</h2><p class="intro">${this.text('codeIntro')}</p><form data-form="activate">${field('code','Mã cấp lượt','','text','required autocomplete="off" placeholder="Nhập mã của bạn" maxlength="24" style="text-transform:uppercase"')}<p class="inline-error" data-error></p><button class="btn full" type="submit">Nhận lượt quay ${icon('arrow')}</button></form><div class="notice">${icon('info')}<span>Mã dùng thử: <button class="text-button" data-action="fill-code"><strong>ANNI2026</strong></button> · Cộng 2 lượt.</span></div>`);}
  accountDialog(){if(!this.user){this.loginDialog();return;}this.modal(`<div class="modal-symbol">${icon('user')}</div><h2 class="serif">Xin chào ${e(this.user.name||'bạn')}.</h2><p class="intro">Số điện thoại ${e(this.user.phone)} · Tài khoản trải nghiệm</p>${this.recoveryMarkup()}<form data-form="name">${field('name','Tên của bạn',this.user.name,'text','required minlength="2" maxlength="80" autocomplete="name"')}<p class="inline-error" data-error></p><button class="btn full" type="submit">Lưu thông tin</button></form><button class="text-button" style="width:100%;margin-top:15px" data-action="logout">${icon('logout')}Đăng xuất tài khoản</button><p class="legal-note">Mã khôi phục không thể lấy lại chỉ bằng số điện thoại. Hãy lưu mã trước khi đăng xuất.</p>`);}
  async startSpin(){if(this.spinning)return;if(!this.user){this.loginDialog('spin');return;}
    const buttons=[document.getElementById('spin-btn'),document.getElementById('mobile-spin-btn')].filter(Boolean);this.sound.activate();this.spinning=true;for(const button of buttons){button.disabled=true;button.innerHTML=`${icon('wheel')}<span class="spinning-label">MAY MẮN ĐANG ĐẾN…</span>`;}
    try{const result=await this.game.spin(this.userId,this.source,token('REQ'));if(result.recoveryCode)sessionStorage.setItem('anni-pending-recovery-'+this.userId,result.recoveryCode);
      const index=this.state.prizes.findIndex(p=>p.id===result.spin.prize.id),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;this.sound.spin(reduced?500:5000);await this.wheel.spin(index,this.state.prizes.length,reduced);
      this.wheelAngle=this.wheel.rotation;this.state=this.game.snapshot();this.spinning=false;this.render();this.resultDialog(result);if(result.voucher){this.sound.win();confetti(this.theme.confetti);}
    }catch(error){this.spinning=false;this.render();this.toast(error.message);}
  }
  resultDialog(result){
    const won=!!result.voucher,theme=this.theme,festival=!!theme.scene;
    const heading=festival?`<div class="festival-result-heading">${this.themeDecor(theme,this.appearance.decorations)}<span class="festival-result-occasion">${e(theme.occasion)}</span><strong class="serif">${won?e(theme.message):this.text('loseTitle')}</strong><span>${e(this.content.brand.name)}</span></div>`:'';
    this.modal(`<div class="result ${festival?'festival-result':''}">${heading}<div class="result-content"><div class="modal-symbol">${symbol(result.spin.prize)}</div><small>${won?this.text('winEyebrow'):this.text('loseEyebrow')}</small><h2 class="serif">${won?e(result.spin.prize.name):this.text('loseTitle')}</h2><p class="intro">${won?this.text('winMessage'):e(result.spin.prize.terms)}</p>${won?`<p class="hint">${e(result.spin.prize.terms)}</p>${this.recoveryMarkup()}${!this.user.name?`<form data-form="claim">${field('name','Tên của bạn','','text','required minlength="2" maxlength="80" placeholder="Tên bạn muốn hiển thị"')}<p class="inline-error" data-error></p><button class="btn full" type="submit">Lưu tên & xem quà ${icon('arrow')}</button></form>`:'<button class="btn full" data-action="go-wallet">'+this.text('walletButton')+' '+icon('arrow')+'</button>'}`:'<button class="btn full" data-action="close">'+this.text('continueButton')+' '+icon('arrow')+'</button>'}<div class="result-banner">Bản trải nghiệm · Phần thưởng mẫu không có giá trị sử dụng.</div></div></div>`);
    if(festival)document.querySelector('dialog').classList.add('festival-dialog');
  }
  voucherHistory(v){
    return v.redeemedAt?`<div class="redemption-receipt" role="status">${icon('check')}<div><strong>Voucher đã được sử dụng</strong><p>${e(redemptionSource(v))} · ${e(v.redeemedBy||'Nhân viên')}<br>${dateTimeLabel(v.redeemedAt)}</p><small>Voucher này không thể dùng lại.</small></div></div>`:'';
  }
  voucherDetails(v){
    return `<div class="voucher-code ${v.redeemedAt?'used-code':''}">${e(v.code)}</div><div class="detail-row"><span>Trạng thái</span><span class="badge ${statusOf(v)==='active'?'':'gray'}">${statusText(statusOf(v))}</span></div><div class="detail-row"><span>Hạn sử dụng</span><span>${dateLabel(v.expiresAt)}</span></div><div class="detail-row"><span>Áp dụng tại</span><span>${e(v.branch)}</span></div><div class="notice">${icon('info')}<span>${e(v.prize.terms)}</span></div>${this.voucherHistory(v)}`;
  }
  showVoucherDetails(v,by){
    const active=statusOf(v)==='active';
    this.modal(`<div class="modal-symbol">${icon(v.prize.icon)}</div><h2 class="serif">${e(v.prize.name)}</h2><p class="intro">${active?this.text('voucherUseIntro'):'Xem trạng thái và thông tin voucher của bạn.'}</p>${this.voucherDetails(v)}${active?`<button class="text-button voucher-copy" data-action="copy" data-value="${e(v.code)}">${icon('copy')}Sao chép mã voucher</button><button class="btn full" data-action="${by==='customer'?'use-voucher':'confirm-redeem'}" data-id="${v.id}" data-value="${v.code}">${icon('check')}${by==='customer'?'Sử dụng voucher':'Đánh dấu đã sử dụng'}</button>`:`<button class="btn full secondary" disabled>${statusText(statusOf(v))}</button>`}<p class="legal-note">Voucher mẫu không có giá trị thanh toán.</p>`);
    this.voucherView={code:v.code,by,confirm:false};
  }
  voucherDialog(id){
    this.state=this.game.snapshot();
    const v=this.state.vouchers.find(x=>x.id===id&&x.userId===this.userId);
    if(v)this.showVoucherDetails(v,'customer');
  }
  confirmVoucherUse(code,by='staff'){
    this.state=this.game.snapshot();
    const v=this.state.vouchers.find(x=>x.code===code&&(by==='staff'||x.userId===this.userId));
    if(!v){this.closeDialog();this.toast('Không tìm thấy voucher trong tài khoản này.');return;}
    if(statusOf(v)!=='active'){this.showVoucherDetails(v,by);return;}
    const u=this.state.users.find(x=>x.id===v.userId);
    this.modal(`<div class="modal-symbol">${icon(by==='customer'?'ticket':'store')}</div><h2 class="serif">${by==='customer'?'Sử dụng voucher này?':'Đánh dấu đã sử dụng?'}</h2><p class="intro">${by==='customer'?'Hãy đưa voucher cho nhân viên kiểm tra điều kiện trước khi xác nhận tại quầy.':'Xác nhận khi khách đã sử dụng ưu đãi tại cửa hàng, kể cả khi khách chưa bấm trong ví quà.'}</p><h3>${e(v.prize.name)}</h3>${by==='staff'?`<div class="detail-row"><span>Khách hàng</span><span>${e(u?.name||'Chưa nhập tên')}<br>${e(u?.phone)}</span></div>`:''}${this.voucherDetails(v)}<p class="use-warning">Sau khi xác nhận, voucher sẽ chuyển sang <strong>Đã sử dụng</strong> và không thể dùng lại.</p><div class="form-actions use-actions"><button class="btn secondary" data-action="close">Để sau</button><button class="btn" data-action="${by==='customer'?'customer-redeem':'redeem'}" data-value="${v.code}">${by==='customer'?'Xác nhận sử dụng':'Đánh dấu đã sử dụng'}</button></div>`);
    this.voucherView={code:v.code,by,confirm:true};
  }
  refreshVoucherViews(){
    if(this.spinning||this.redeeming)return;
    const view=this.voucherView;
    if(document.querySelector('dialog[open]')&&!view)return;
    this.draft=null;this.render();
    if(view){
      if(view.confirm)this.confirmVoucherUse(view.code,view.by);
      else {const v=this.state.vouchers.find(x=>x.code===view.code&&(view.by==='staff'||x.userId===this.userId));if(v)this.showVoucherDetails(v,view.by);else this.closeDialog();}
    }
  }
  async redeemVoucher(code,by,button){
    if(this.redeeming)return;
    this.redeeming=true;button.disabled=true;
    try{
      const v=by==='customer'?await this.game.useVoucher(this.userId,code):await this.game.redeem(code);
      if(by==='customer')this.walletFilter='used';
      this.closeDialog();this.render();this.showVoucherDetails(v,by);
      this.toast('Đã ghi nhận sử dụng. Voucher không thể dùng lại.');
    }catch(error){
      this.closeDialog();this.render();
      const v=this.state.vouchers.find(x=>x.code===code&&(by==='staff'||x.userId===this.userId));
      if(v)this.showVoucherDetails(v,by);
      this.toast(error.message);
    }finally{this.redeeming=false;}
  }
  prizeDialog(id){this.draft ||= clone(this.state.prizes);const p=this.draft.find(p=>p.id===id)||{id:'',name:'',short:'',kind:'drink',weight:0,stock:10,days:7,color:'#A4B4A0',icon:'gift',terms:'Quà mẫu, chưa có giá trị sử dụng.',image:''};this.editingId=p.id;this.prizeImage=p.image;this.modal(`<h2 class="serif">${id?'Chỉnh phần thưởng':'Thêm một món quà'}</h2><p class="intro">Tên ngắn hiển thị trên vòng quay. Nội dung đầy đủ hiển thị khi trúng và trong ví quà.</p><form data-form="prize"><div class="fields">${field('name','Tên phần thưởng',p.name,'text','required maxlength="70"')}${field('short','Tên ngắn trên vòng quay',p.short,'text','required maxlength="22"')}<div class="field"><label for="f-kind">Loại phần thưởng</label><select name="kind" id="f-kind">${[['drink','Đồ uống / quà tặng'],['percent','Giảm phần trăm'],['amount','Giảm tiền'],['lose','May mắn lần sau']].map(([v,t])=>`<option value="${v}" ${p.kind===v?'selected':''}>${t}</option>`).join('')}</select></div>${field('weight','Tỷ lệ gốc (%)',p.weight/100,'number','required min="0" max="100" step="0.01"')}${field('stock','Số quà còn lại',p.stock??0,'number','required min="0" max="1000000" step="1"')}${field('days','Hạn voucher (ngày)',p.days,'number','required min="1" max="365"')}${field('color','Màu ô vòng quay',p.color,'color')}<div class="field"><label for="f-icon">Biểu tượng</label><select name="icon" id="f-icon">${[['gift','Hộp quà'],['cup','Cà phê'],['ticket','Voucher'],['spark','Ngôi sao'],['leaf','Chiếc lá']].map(([v,t])=>`<option value="${v}" ${p.icon===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="field full"><label for="f-terms">Nội dung & điều kiện sử dụng</label><textarea name="terms" id="f-terms" required maxlength="500">${e(p.terms)}</textarea></div><div class="field full"><label for="prize-image">Ảnh phần thưởng (tùy chọn)</label><input type="file" id="prize-image" accept="image/png,image/jpeg,image/webp"><small>PNG, JPG hoặc WebP, tối đa 600 KB. ${p.image?'Đã có ảnh.':''}</small><button class="text-button" type="button" data-action="remove-image">Xóa ảnh phần thưởng</button></div></div><p class="inline-error" data-error></p><div class="form-actions">${id?'<button class="btn danger" type="button" data-action="delete-prize" data-id="'+id+'">Xóa ô</button>':''}<button class="btn" type="submit">Áp dụng vào bản nháp</button></div><p class="legal-note">Sau đó bấm “Lưu phần thưởng” để kiểm tra tổng 100% và áp dụng.</p></form>`,true);}
  codeAdminDialog(id){const existing=this.state.codes.find(c=>c.id===id),now=new Date();const c=existing||{id:'',code:'',turns:2,maxUses:100,perPhone:1,period:'all',creditDays:7,starts:now.toISOString(),ends:new Date(+now+30*86400000).toISOString(),active:true,branch:this.state.settings.branch};this.editingId=c.id;this.modal(`<h2 class="serif">${id?'Chỉnh mã cấp lượt':'Tạo mã cấp lượt'}</h2><p class="intro">Thiết lập riêng cho từng mã. Thu ngân cung cấp mã cho khách trước khi quay.</p><form data-form="code-admin"><div class="fields">${field('code','Mã chương trình',c.code,'text','required maxlength="24" placeholder="Ví dụ: ANNI-WEEKEND"')}${field('branch','Chi nhánh / ghi chú đối soát',c.branch,'text','required maxlength="80"')}${field('turns','Lượt được cấp / lần nhập',c.turns,'number','required min="1" max="100"')}${field('maxUses','Tổng số lần được kích hoạt',c.maxUses,'number','required min="1" max="100000"')}${field('perPhone','Số lần kích hoạt / SĐT',c.perPhone,'number','required min="1" max="100"')}<div class="field"><label for="f-period">Chu kỳ giới hạn mỗi SĐT</label><select name="period" id="f-period"><option value="all" ${c.period==='all'?'selected':''}>Toàn thời gian hiệu lực</option><option value="day" ${c.period==='day'?'selected':''}>Mỗi ngày (giờ Việt Nam)</option></select></div>${field('starts','Bắt đầu (giờ trên thiết bị)',datetimeLocal(c.starts),'datetime-local','required')}${field('ends','Hết hạn nhập mã (giờ trên thiết bị)',datetimeLocal(c.ends),'datetime-local','required')}${field('creditDays','Lượt đã cấp có hạn (ngày)',c.creditDays,'number','required min="1" max="365"')}</div><label class="check-field"><input type="checkbox" name="active" ${c.active?'checked':''}>Cho phép kích hoạt mã</label><p class="inline-error" data-error></p><div class="form-actions"><button class="btn secondary" type="button" data-action="generate-code">Tạo mã ngẫu nhiên</button><button class="btn" type="submit">${icon('check')}Lưu mã</button></div></form>`,true);}
  lookup(code){
    this.staffLookupCode=code.trim().toUpperCase();this.state=this.game.snapshot();
    const v=this.state.vouchers.find(x=>x.code===this.staffLookupCode),target=document.getElementById('redeem-result'),error=document.getElementById('redeem-error');
    if(!target)return;error.textContent='';
    if(!v){target.innerHTML='';error.textContent='Không tìm thấy voucher. Kiểm tra lại mã khách cung cấp.';return;}
    const user=this.state.users.find(u=>u.id===v.userId),active=statusOf(v)==='active';
    target.innerHTML=`<div class="redeem-detail"><h3 class="serif">${e(v.prize.name)}</h3><div class="detail-row"><span>Khách hàng</span><span>${e(user?.name||'Chưa nhập tên')}</span></div><div class="detail-row"><span>Số điện thoại</span><span>${e(user?.phone)}</span></div>${this.voucherDetails(v)}<button class="btn full" data-action="confirm-redeem" data-value="${v.code}" ${active?'':'disabled'}>${icon('check')}${active?'Đánh dấu đã sử dụng':statusText(statusOf(v))}</button></div>`;
  }
  async onClick(event){if(this.spinning&&event.target.closest('a[href^="#"]')){event.preventDefault();return;}const target=event.target.closest('[data-action]');if(!target)return;if(this.spinning&&target.dataset.action!=='sound'){event.preventDefault();return;}const action=target.dataset.action,id=target.dataset.id,value=target.dataset.value;try{switch(action){
    case 'source':{const mobile=!!target.closest('.mobile-play-actions');this.source=value;this.render();document.querySelector(`${mobile?'.mobile-play-actions':'.play-card'} [data-value="${this.source}"]`)?.focus({preventScroll:true});break;}
    case 'sound':this.sound.activate();this.sound.toggle();target.innerHTML=icon(this.sound.enabled?'sound':'mute');target.setAttribute('aria-label',this.sound.enabled?'Tắt âm thanh':'Bật âm thanh');target.setAttribute('aria-pressed',String(this.sound.enabled));break;
    case 'spin':await this.startSpin();break;
    case 'account':this.accountDialog();break;
    case 'login':this.loginDialog();break;
    case 'sample-phone':document.querySelector('[name=phone]').value='0900000001';break;
    case 'fill-code':document.querySelector('[name=code]').value='ANNI2026';break;
    case 'code':this.codeDialog();break;
    case 'close':this.closeDialog();break;
    case 'go-play':this.closeDialog();location.hash='play';break;
    case 'go-wallet':this.closeDialog();location.hash='wallet';break;
    case 'wallet-filter':this.walletFilter=value;this.render();break;
    case 'voucher':this.voucherDialog(id);break;
    case 'copy':await this.copy(value);break;
    case 'copy-recovery':await this.copy(this.pendingRecovery());break;
    case 'recovery':this.modal(`<h2 class="serif">Giữ lại chìa khóa ví quà.</h2>${this.recoveryMarkup()}<button class="btn full" data-action="recovery-saved">Tôi đã lưu mã khôi phục</button>`);break;
    case 'recovery-saved':sessionStorage.removeItem('anni-pending-recovery-'+this.userId);this.closeDialog();this.render();this.toast('Đã xác nhận. Hãy giữ mã khôi phục ở nơi riêng tư.');break;
    case 'logout':if(this.pendingRecovery()){this.modal(`<h2 class="serif">Lưu mã trước khi rời đi.</h2>${this.recoveryMarkup()}<button class="btn full" data-action="logout-confirm">Tôi đã lưu mã, đăng xuất</button>`);}else await this.logout();break;
    case 'logout-confirm':await this.logout();break;
    case 'demo-info':this.modal(`<div class="modal-symbol">${icon('info')}</div><h2 class="serif">Một bản mẫu để cùng thử.</h2><p class="intro">Bạn có thể thử vòng quay, ví quà, quản trị và đổi voucher. Dữ liệu được lưu trong trình duyệt, không đồng bộ giữa điện thoại và laptop.</p><ul class="help-list"><li>Dùng số mẫu 0900000001 và mã ANNI2026.</li><li>Quản trị demo mở để thử thao tác, chưa có xác thực nhân viên.</li><li>Không dùng dữ liệu hay quà thật.</li><li>Xóa dữ liệu trình duyệt sẽ xóa ví và cấu hình mẫu.</li><li>Bản chính thức sẽ xác định kết quả, giữ tồn kho và lưu ví trên máy chủ.</li></ul><button class="btn full" data-action="close">Đã hiểu</button>`);break;
    case 'content-section':this.contentEditor.section=value;this.render();document.querySelector(`[data-action="content-section"][data-value="${value}"]`)?.focus({preventScroll:true});break;
    case 'content-reset-field':this.contentEditor.resetField(value);this.render();document.getElementById('content-'+value)?.focus({preventScroll:true});break;
    case 'content-remove-logo':this.contentEditor.uploadToken++;this.contentEditor.uploading=false;this.contentEditor.draft.brand.logo='';this.render();break;
    case 'content-reset-section':this.contentRestoreDialog('section');break;
    case 'content-reset-all':this.contentRestoreDialog('all');break;
    case 'content-previous':if(this.state.settings.contentPrevious)this.contentRestoreDialog('previous');break;
    case 'content-discard':if(this.contentEditor.dirty)this.contentRestoreDialog('discard');else {this.contentEditor=null;this.render();}break;
    case 'content-restore-confirm':{
      this.state=this.game.snapshot();
      if(value==='all')this.contentEditor.resetAll();
      else if(value==='section')this.contentEditor.resetSection();
      else if(value==='previous'&&this.state.settings.contentPrevious)this.contentEditor.previous(this.state.settings);
      else if(value==='discard')this.contentEditor=null;
      this.closeDialog();this.render();break;
    }
    case 'theme-select':this.themeDraft={...(this.themeDraft||this.appearance),theme:getTheme(value).id};this.render();document.querySelector(`[data-action="theme-select"][data-value="${this.themeDraft.theme}"]`)?.focus({preventScroll:true});break;
    case 'theme-discard':this.themeDraft=null;this.render();this.toast('Đã trở về chủ đề đang sử dụng.');break;
    case 'add-prize':this.prizeDialog();break;
    case 'edit-prize':this.prizeDialog(id);break;
    case 'remove-image':this.prizeImage='';document.getElementById('prize-image').value='';this.toast('Ảnh đã được gỡ khỏi bản nháp.');break;
    case 'delete-prize':this.draft=this.draft.filter(p=>p.id!==id);this.closeDialog();this.render();break;
    case 'discard-prizes':this.draft=null;this.render();break;
    case 'save-prizes':await this.game.savePrizes(this.draft);this.draft=null;this.render();this.toast('Đã lưu phần thưởng và tỷ lệ.');break;
    case 'add-code':this.codeAdminDialog();break;
    case 'edit-code':this.codeAdminDialog(id);break;
    case 'generate-code':document.querySelector('[name=code]').value=token('ANNI-',6);break;
    case 'staff-lookup':this.staffLookupCode=value;if(this.route==='admin/redeem')this.lookup(value);else location.hash='admin/redeem';break;
    case 'confirm-redeem':this.confirmVoucherUse(value,'staff');break;
    case 'redeem':await this.redeemVoucher(value,'staff',target);break;
    case 'use-voucher':{const v=this.game.snapshot().vouchers.find(x=>x.id===id&&x.userId===this.userId);if(v)this.confirmVoucherUse(v.code,'customer');break;}
    case 'customer-redeem':await this.redeemVoucher(value,'customer',target);break;
    case 'export-report':this.exportReport();break;
    case 'export-config':this.download('ANNI-COFFEE-cau-hinh-mau.json',JSON.stringify({settings:this.state.settings,prizes:this.state.prizes,codes:this.state.codes.map(({uses,...c})=>c)},null,2),'application/json');break;
    case 'reset':this.modal(`<h2 class="serif">Bắt đầu lại bản demo?</h2><p class="intro">Thao tác này xóa toàn bộ lượt quay, tài khoản, voucher và cấu hình thử nghiệm trên trình duyệt này, rồi nạp lại bộ quà mẫu.</p><div class="form-actions"><button class="btn secondary" data-action="close">Giữ dữ liệu</button><button class="btn danger" data-action="reset-confirm">Xóa & khôi phục mẫu</button></div>`);break;
    case 'reset-confirm':this.contentEditor=null;await this.repository.reset();await this.logout();this.draft=null;this.render();this.toast('Đã khôi phục dữ liệu mẫu.');break;
  }}catch(error){this.toast(error.message);}}
  async onForm(form){const data=Object.fromEntries(new FormData(form)),kind=form.dataset.form,error=form.querySelector('[data-error]'),button=form.querySelector('[type=submit]');if(error)error.textContent='';if(button)button.disabled=true;try{switch(kind){
    case 'login':{const user=await this.game.login(data.phone,data.recovery);this.userId=user.id;localStorage.setItem('anni-demo-session',user.id);this.closeDialog();this.render();const after=this.afterLogin;this.afterLogin='';if(after==='spin')await this.startSpin();else if(after==='code')this.codeDialog();else this.toast('Đã mở tài khoản trải nghiệm.');break;}
    case 'activate':{const credit=await this.game.activateCode(this.userId,data.code);this.source='earned';this.closeDialog();this.render();this.toast(`Đã cộng ${credit.remaining} lượt. Dùng trước ${dateLabel(credit.expiresAt)}.`);break;}
    case 'name':case 'claim':await this.game.saveName(this.userId,data.name);this.closeDialog();this.render();if(kind==='claim')location.hash='wallet';this.toast('Đã lưu thông tin của bạn.');break;
    case 'prize':{const p={id:this.editingId||token('P'),name:data.name.trim(),short:data.short.trim(),kind:data.kind,weight:basisPoints(data.weight),stock:data.kind==='lose'?null:Number(data.stock),days:Number(data.days),color:data.color,icon:data.icon,terms:data.terms.trim(),image:this.prizeImage};const index=this.draft.findIndex(x=>x.id===p.id);if(index>=0)this.draft[index]=p;else this.draft.push(p);this.closeDialog();this.render();this.toast('Đã cập nhật bản nháp. Bấm Lưu phần thưởng để áp dụng.');break;}
    case 'code-admin':await this.game.saveCode({...data,id:this.editingId,active:data.active==='on',starts:asISO(data.starts),ends:asISO(data.ends)});this.closeDialog();this.render();this.toast('Đã lưu mã cấp lượt quay.');break;
    case 'appearance':await this.game.saveAppearance(this.themeDraft||this.appearance);this.themeDraft=null;this.render();this.toast('Đã áp dụng chủ đề '+this.theme.name+'.');break;
    case 'content':{const editor=this.contentEditor;if(editor.uploading)throw new Error('Vui lòng chờ logo xử lý xong.');await this.game.saveContent(editor.draft,editor.revision);this.contentEditor=new ContentEditor(this.game.snapshot().settings);this.contentEditor.section=editor.section;this.contentEditor.themeId=editor.themeId;this.render();this.toast('Đã lưu nội dung và thương hiệu.');break;}
    case 'settings':await this.game.saveSettings({...data,active:data.active==='on',start:asISO(data.start),end:asISO(data.end)});this.render();this.toast('Đã lưu thiết lập chiến dịch.');break;
    case 'lookup':this.lookup(data.code);break;
  }}catch(err){if(kind==='content')this.toast(err.message);if(error)error.textContent=err.message;else if(kind==='lookup')document.getElementById('redeem-error').textContent=err.message;else this.toast(err.message);}finally{if(button?.isConnected)button.disabled=false;}}
  onInput(event){const target=event.target;
    if(target.dataset.contentField){const editor=this.contentEditor;editor.setField(target.dataset.contentField,target.value);document.querySelector(`[data-content-count="${target.dataset.contentField}"]`).textContent=target.value.length;editor.sync(this.state.prizes,this.state.settings);return;}
    if(target.id==='content-theme'){this.contentEditor.themeId=getTheme(target.value).id;this.render();document.getElementById('content-theme').focus({preventScroll:true});return;}
    if(target.id==='content-logo'&&target.files[0]){this.contentLogo(target.files[0]);return;}
if(target.id==='theme-decorations'){this.themeDraft={...(this.themeDraft||this.appearance),decorations:target.checked};this.render();document.getElementById('theme-decorations').focus({preventScroll:true});return;}if(target.dataset.prize!==undefined){const p=this.draft[Number(target.dataset.prize)];p[target.dataset.field]=target.dataset.field==='weight'?(Math.abs(Number(target.value)*100-Math.round(Number(target.value)*100))<1e-7?Math.round(Number(target.value)*100):NaN):Number(target.value);const total=this.draft.reduce((n,p)=>n+p.weight,0),node=document.getElementById('total-weight');node.textContent=percentLabel(total);node.classList.toggle('invalid',Math.abs(total-10000)>1e-7);try{const weights=ProbabilityPolicy.weights(this.draft,this.state.settings.mode);weights.forEach((p,i)=>{document.querySelector(`[data-effective="${i}"]`).textContent=percentLabel(p.effective);});}catch{document.querySelectorAll('[data-effective]').forEach(n=>n.textContent='—');}}
    if(target.id==='report-search'||target.id==='report-status'){this.reportFilter=document.getElementById('report-search').value;this.reportStatus=document.getElementById('report-status').value;document.getElementById('report-table').innerHTML=this.reportTable();}
    if(target.id==='prize-image'&&target.files[0]){const file=target.files[0];if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>600*1024){this.toast('Chọn ảnh PNG, JPG hoặc WebP không quá 600 KB.');target.value='';return;}const reader=new FileReader();reader.onload=()=>{this.prizeImage=reader.result;this.toast('Đã chọn ảnh. Lưu bản nháp để áp dụng.');};reader.readAsDataURL(file);}
  }
  async logout(){if(this.userId)sessionStorage.removeItem('anni-pending-recovery-'+this.userId);this.userId=null;localStorage.removeItem('anni-demo-session');this.closeDialog();this.render();this.toast('Đã đăng xuất.');}
  async copy(value){if(!value)return;try{await navigator.clipboard.writeText(value);this.toast('Đã sao chép.');}catch{this.modal(`<h2 class="serif">Sao chép mã</h2><p class="intro">Trình duyệt chưa cho phép sao chép tự động. Nhấn giữ hoặc chọn mã bên dưới để sao chép.</p><input readonly value="${e(value)}" aria-label="Mã cần sao chép">`);}}
  download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
  exportReport(){const quote=value=>'"'+String(value??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const rows=[['Tên','Số điện thoại','Phần thưởng','Mã voucher','Ngày trúng','Hạn sử dụng','Trạng thái','Nguồn xác nhận','Người xác nhận','Ngày sử dụng'],...this.reportRows().map(v=>{const u=this.state.users.find(x=>x.id===v.userId);return [u?.name,u?.phone,v.prize.name,v.code,v.at,v.expiresAt,statusText(statusOf(v)),v.redeemedAt?redemptionSource(v):'',v.redeemedBy,v.redeemedAt];})];this.download('ANNI-COFFEE-danh-sach-trung.csv','\uFEFF'+rows.map(r=>r.map(quote).join(',')).join('\r\n'),'text/csv;charset=utf-8');this.toast('Đã xuất danh sách đang lọc.');}
}
try{new App();}catch(error){document.getElementById('app').innerHTML=`<div class="shell"><section class="page"><h1 class="serif">Chưa mở được bản trải nghiệm.</h1><p class="notice">${e(error.message)}</p><p class="hint">Vui lòng bật lưu trữ trong trình duyệt. Nếu dữ liệu mẫu bị lỗi, hãy xóa dữ liệu của riêng trang này để bắt đầu lại.</p></section></div>`;}
